CREATE TABLE item_generations(item_id TEXT PRIMARY KEY REFERENCES work_items(id), generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE dispatches(attempt_id TEXT PRIMARY KEY REFERENCES attempts(id), request_json TEXT NOT NULL, digest TEXT NOT NULL, thread_id TEXT NOT NULL, interrupt_id TEXT NOT NULL, execution_generation INTEGER NOT NULL, pid INTEGER, process_started TEXT, deadline INTEGER, same_family_warning INTEGER NOT NULL DEFAULT 0);
CREATE TABLE model_queue(id TEXT PRIMARY KEY, attempt_id TEXT, route TEXT NOT NULL, provider TEXT NOT NULL, model TEXT NOT NULL, urgent INTEGER NOT NULL, sprint_order INTEGER NOT NULL, enqueued_at INTEGER NOT NULL, execution_generation INTEGER NOT NULL);
CREATE TABLE route_health(route TEXT PRIMARY KEY, available INTEGER NOT NULL DEFAULT 0, model TEXT, verified_at INTEGER, error TEXT);
CREATE TABLE role_families(item_id TEXT NOT NULL REFERENCES work_items(id),role TEXT NOT NULL,family TEXT NOT NULL,PRIMARY KEY(item_id,role));
CREATE TABLE proxy_calls(id TEXT PRIMARY KEY,attempt_id TEXT,request_digest TEXT NOT NULL,state TEXT NOT NULL,response_sha TEXT,created_at INTEGER NOT NULL);
ALTER TABLE dispatches ADD COLUMN route_json TEXT;
ALTER TABLE work_items ADD COLUMN queue_order INTEGER NOT NULL DEFAULT 9223372036854775807;
CREATE TABLE route_failures(route TEXT PRIMARY KEY, failures INTEGER NOT NULL, last_failure INTEGER NOT NULL);
CREATE TABLE supervised_processes(id TEXT PRIMARY KEY,pid INTEGER NOT NULL,process_started TEXT NOT NULL);
ALTER TABLE dispatches ADD COLUMN quota_pending INTEGER NOT NULL DEFAULT 0;
ALTER TABLE outbox ADD COLUMN next_attempt_at INTEGER NOT NULL DEFAULT 0;
